-- Administrative test only. Every test write is rolled back; no provider calls.
begin;
do $$declare patient uuid;patient_user uuid;clinician uuid;caregiver uuid;i uuid;j uuid;f uuid;test_loop uuid;item uuid;plan uuid;outbox uuid;job uuid;source_path text;other_loop uuid;result jsonb;begin
 select id,user_id into patient,patient_user from public.patients where synthetic order by created_at limit 1;
 select user_id into clinician from private.memberships where patient_id=patient and role='clinician' and active limit 1;
 select user_id into caregiver from private.memberships where patient_id=patient and role='caregiver' and active limit 1;
 if patient is null or clinician is null then raise exception 'Synthetic identity fixtures required';end if;
 perform set_config('request.jwt.claim.sub',patient_user::text,true);
 begin perform public.operational_health(patient);raise exception 'Patient read backend health';exception when insufficient_privilege then null;end;
 i:=public.submit_intake(patient,'Rollback fixture','Unmatched note',null,'6bd6724a-4226-4108-b09a-a064062e3a52');
 j:=public.submit_intake(patient,'Rollback fixture','Unmatched note',null,'6bd6724a-4226-4108-b09a-a064062e3a52');
 if i<>j then raise exception 'Duplicate intake';end if;
 begin perform public.submit_intake(patient,'Changed payload','Unmatched note',null,'6bd6724a-4226-4108-b09a-a064062e3a52');raise exception 'Expected mismatch rejection';exception when raise_exception then if sqlerrm='Expected mismatch rejection' then raise;end if;end;
 begin perform public.operational_snapshot(patient,now()-interval '7 days',now());raise exception 'Patient read team summary';exception when insufficient_privilege then null;end;
 begin perform public.resolve_intake(i,'acknowledge',null,'Patient cannot resolve');raise exception 'Patient resolved team note';exception when insufficient_privilege then null;end;
 perform public.record_processing_failure(patient,'report','timeout',gen_random_uuid());
 perform set_config('request.jwt.claim.sub',clinician::text,true);
 result:=public.operational_health(patient);if result#>>'{scheduler,active}' is distinct from 'true' then raise exception 'Scheduler configuration missing from health snapshot';end if;
 result:=public.operational_snapshot(patient,now()-interval '7 days',now());
 if jsonb_array_length(result->'intake')<1 then raise exception 'Summary lost intake';end if;
 result:=public.resolve_intake(i,'acknowledge',null,'Read the source; no care task changed');
 if result->>'state'<>'resolved' then raise exception 'Acknowledgment failed';end if;
 select id into plan from public.care_plans where patient_id=patient and active and status='confirmed' limit 1;
 insert into public.care_plan_items(plan_id,patient_id,domain,label,requires_human_review) values(plan,patient,'test','Rollback operations investigation',true) returning id into item;
 insert into public.care_loops(item_id,patient_id,due_at) values(item,patient,now()-interval '1 hour') returning id into test_loop;
 source_path:=patient::text||'/'||gen_random_uuid()::text||'.pdf';
 insert into storage.objects(bucket_id,name) values('care-evidence',source_path);
 perform set_config('request.jwt.claim.sub',patient_user::text,true);
 i:=public.submit_intake(patient,'Rollback file','Review association',source_path,gen_random_uuid());
 begin insert into public.evidence(patient_id,loop_id,submitted_by,label,storage_path,content_sha256) values(patient,test_loop,patient_user,'Rollback file',source_path,repeat('b',64));raise exception 'Unmatched file became evidence';exception when raise_exception then if sqlerrm='Unmatched file became evidence' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',clinician::text,true);
 insert into public.care_loops(item_id,patient_id,due_at) values(item,patient,now()-interval '2 hours') returning id into other_loop;
 perform public.resolve_intake(i,'match',other_loop,'Concurrent corrected association');
 begin insert into public.evidence(patient_id,loop_id,submitted_by,label,storage_path,content_sha256) values(patient,test_loop,patient_user,'Stale confirmation',source_path,repeat('b',64));raise exception 'Stale match accepted';exception when raise_exception then if sqlerrm='Stale match accepted' then raise;end if;end;
 perform public.resolve_intake(i,'match',test_loop,'Verified association');
 insert into public.evidence(patient_id,loop_id,submitted_by,label,storage_path,content_sha256) values(patient,test_loop,patient_user,'Rollback file',source_path,repeat('b',64));
 if (select state from public.intake_items where id=i)<>'resolved' then raise exception 'Evidence and intake not atomic';end if;
 perform set_config('request.jwt.claim.sub',patient_user::text,true);
 perform public.resolve_intake(i,'finish',null,'Recovery acknowledgment');
 perform set_config('request.jwt.claim.sub',clinician::text,true);
 insert into public.message_outbox(patient_id,loop_id,recipient_role,body,delivery_status) values(patient,test_loop,'patient','Rollback fixture only','pending') returning id into outbox;
 job:=private.prepare_delivery(outbox,'whatsapp');
 if (select state from public.delivery_jobs where id=job)<>'blocked' then raise exception 'Default channel not blocked';end if;
 update public.delivery_jobs set state='pending' where id=job;
 if private.claim_delivery(job,1) is not null then raise exception 'Disabled channel claimed';end if;
 update private.channel_gates set enabled=true where channel='whatsapp';
 if private.claim_delivery(job,1) is not null then raise exception 'Unenrolled channel claimed';end if;
 insert into private.channel_enrollments(patient_id,channel,recipient_reference,consented,verified_at) values(patient,'whatsapp','fixture-not-a-phone',true,now());
 result:=private.claim_delivery(job,1);if result->>'state'<>'reserved' then raise exception 'Durable claim failed';end if;
 if private.claim_delivery(job,1) is not null then raise exception 'Duplicate claim';end if;
 perform private.delivery_result(job,'rollback-delivered','delivered','fixture-provider-id');
 perform private.delivery_result(job,'rollback-accepted-late','accepted','fixture-provider-id');
 perform private.delivery_result(job,'rollback-delivered','delivered','fixture-provider-id');
 if (select state from public.delivery_jobs where id=job)<>'delivered' then raise exception 'Callback regression';end if;
 if (select state from public.care_loops where id=test_loop)<>'DUE' then raise exception 'Delivery closed a care task';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 begin perform public.operational_snapshot(patient,now()-interval '7 days',now());raise exception 'Unassigned summary access';exception when insufficient_privilege then null;end;
 if has_function_privilege('anon','public.submit_intake(uuid,text,text,text,uuid)','execute') or has_function_privilege('authenticated','private.claim_delivery(uuid,integer)','execute') then raise exception 'Unsafe function grants';end if;
 if caregiver is not null then
 perform set_config('request.jwt.claim.sub',caregiver::text,true);
 begin perform public.operational_snapshot(patient,now()-interval '7 days',now());raise exception 'Caregiver clinical summary access';exception when insufficient_privilege then null;end;
 end if;
end$$;
-- Prove row-level policies under an ordinary authenticated identity with no assignment.
select set_config('request.jwt.claim.sub','df6d3397-35b5-4358-aea7-39975e1b5def',true);
set local role authenticated;
do $$begin if exists(select 1 from public.intake_items) or exists(select 1 from public.processing_events) or exists(select 1 from public.delivery_jobs) then raise exception 'RLS exposed unassigned records';end if;end$$;
reset role;
select 'operations assertions passed; transaction rolled back' result;
rollback;
